<?php
namespace Tests\Feature;
use App\Models\{Admin,EventProject,PresalePlan,Distributor,RegistrationCampaign,Team,TeamRoleAssignment,ReportPoint,Incident,SiteFeature,Sponsorship,FreguesiaAgreement,CommunityAward,FeedbackCampaign,FeedbackInvitation,EditorialPost,RallyStop,DrawingContest,DrawingEntry,BarPartnership};
use App\Domain\Tickets\{Ticketing,DrinkWallet};
use App\Domain\Community\Feedback;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Mail};
use Illuminate\Validation\ValidationException;
use Tests\TestCase;
class CommunityContinuityTest extends TestCase {
 use RefreshDatabase;
 private function admin(): void {$this->actingAs(Admin::firstOrCreate(['email'=>'community@example.test'],['name'=>'Admin','password'=>'long-community-password']),'admin');}
 private function invalid(callable $f): void {try{$f();$this->fail('Expected validation error');}catch(ValidationException){$this->assertTrue(true);}}
 private function project(): EventProject {$this->travelTo(\Carbon\Carbon::parse('2026-10-01'));$this->admin();config(['presales.enabled'=>true,'events.privacy_ready'=>true,'events.organizer_name'=>'QAPAS','events.contact_email'=>'info@example.test','registration.live'=>false]);$p=EventProject::create(['name'=>'Community games','slug'=>'community-games','community_version'=>'2026-v1','edition_year'=>2026,'is_public'=>true,'venue'=>'Site','capacity'=>500,'starts_at'=>'2026-12-12 10:00:00','ends_at'=>'2026-12-13 22:00:00']);foreach($p->requirements as $r)$r->update(['status'=>'approved','evidence'=>'Reviewed','reviewed_by'=>'Professional','reviewed_at'=>now()]);return $p;}
 private function plan(EventProject $p): PresalePlan {return PresalePlan::create(['event_project_id'=>$p->id,'name'=>'Participation','kind'=>'admission','unified_benefits'=>true,'terms_version'=>'v1','terms_fr'=>'Dix euros boissons pour tous','terms_pt'=>'Dez euros bebidas para todos','refund_fr'=>'Refund','refund_pt'=>'Reembolso','split_evidence'=>'Allocations approved','billing_procedure'=>'Reviewed invoicing','approval_evidence'=>'Approved','vat_basis_points'=>0,'capacity'=>100,'closes_at'=>'2026-12-01','benefits'=>[],'benefit_cost_cents'=>0,'benefit_evidence'=>'Only drinks included','sales_strategy'=>'fixed','price_cents'=>1000,'drink_credit_cents'=>1000,'drink_cost_cents'=>300,'drink_cost_evidence'=>'Supplier quotation and capacity','drink_credit_terms_fr'=>'Bar les 12 et 13 décembre, de 10 à 22 h','drink_credit_terms_pt'=>'Bar 12 e 13 dezembro, 10h–22h','is_open'=>true]);}
 private function relay(EventProject $p): Distributor {$stand=$p->stands()->create(['name'=>'Village','kind'=>'village','freguesia'=>'Souto','is_public'=>true]);$partner=$stand->partners()->create(['name'=>'Café','relay_slot'=>1,'status'=>'active','mission'=>'Distribution','evidence'=>'Signed']);$d=Distributor::create(['stand_partner_id'=>$partner->id,'name'=>'Café','email'=>'cafe@example.test','password'=>'long-relay-password','contract_evidence'=>'Mandate','is_active'=>true]);$this->actingAs($d,'relay');return $d;}
 private function paid(PresalePlan $p,Distributor $d,array $extra=[]): \App\Models\EventTicket {$t=app(Ticketing::class)->issue($p,array_replace(['buyer_name'=>'Maria','phone'=>'+351912345678','terms_version'=>$p->terms_version,'quote_key'=>$p->quote()['key'],'channel'=>'cash','request_id'=>(string)\Illuminate\Support\Str::uuid()],$extra),$d);app(Ticketing::class)->settle($d,[$t->id],$t->expectedRemittance(),'bank-'.$t->id,'Receipt proof',now());return $t->fresh();}
 private function feature(EventProject $p,string $name='Parking'): SiteFeature {return SiteFeature::create(['event_project_id'=>$p->id,'name'=>$name,'category'=>'parking','geometry'=>['type'=>'Point','coordinates'=>[-7.4,40.3]]]);}
 public function test_seed_adds_cost_once_and_preserves_edits_and_legacy_drafts(): void {$this->seed();$p=EventProject::first();$this->assertSame('community-2026-v1',$p->community_version);$this->assertDatabaseCount('freguesia_agreements',6);$this->assertDatabaseCount('rally_stops',6);$this->assertDatabaseCount('community_awards',1);$this->assertDatabaseCount('report_points',12);$plan=PresalePlan::first();$this->assertSame(1000,$plan->drink_credit_cents);$this->assertNull($plan->drink_cost_cents);$this->assertFalse($plan->is_open);$this->assertStringNotContainsString('Candidatures experts',$p->registrationCampaign->name);$this->assertSame(50000,CommunityAward::first()->budgetLine->unit_gross_cents);$this->assertSame(6,\App\Domain\Teams\ExpertRoles::CORE ? count(\App\Domain\Teams\ExpertRoles::CORE) : 0);$a=FreguesiaAgreement::first();$a->update(['terms_fr'=>'My reviewed draft']);$this->seed();$this->assertSame('My reviewed draft',$a->fresh()->terms_fr);$this->assertDatabaseCount('community_awards',1);$this->assertDatabaseCount('report_points',12);}
 public function test_drinks_are_guaranteed_for_all_paid_tickets_and_reserved_once(): void {$p=$this->project();$plan=$this->plan($p);$d=$this->relay($p);RegistrationCampaign::create(['event_project_id'=>$p->id,'name'=>'Join my team','unified_ticket_terms'=>true,'terms_version'=>'c1','terms_fr'=>'Same ticket','terms_pt'=>'Mesmo bilhete','refund_policy_fr'=>'Refund','refund_policy_pt'=>'Reembolso','billing_procedure'=>'Reviewed','validation_evidence'=>'Reviewed','vat_basis_points'=>0,'closes_at'=>'2026-11-20','is_open'=>true]);$v=$this->paid($plan,$d);$c=$this->paid($plan,$d,['candidate'=>true,'candidate_terms_version'=>'c1','expert_roles'=>['cook','musician']]);$this->assertSame(1000,$c->amount_cents);$this->assertSame(1000,$c->drinkRemaining());$this->assertSame($v->drink_credit_cents,$c->drink_credit_cents);$this->assertSame(0,$c->candidate->credit_cents);DB::table('candidate_registrations')->where('id',$c->candidate_registration_id)->update(['decision'=>'selected']);$this->assertSame(1000,$c->fresh()->drinkRemaining());DB::table('candidate_registrations')->where('id',$c->candidate_registration_id)->update(['decision'=>'not_selected']);$this->assertSame(1000,$c->fresh()->drinkRemaining());$plan->update(['bank_available_cents'=>2000,'refund_reserve_cents'=>0,'bank_evidence'=>'Statement']);$this->assertSame(600,$plan->report()['benefit_reserve_cents']);$this->assertSame(2000,$plan->report()['drink_credit_face_cents']);$this->assertSame(600,$plan->report()['available_cents']);}
 public function test_drink_wallet_is_partial_idempotent_private_and_not_a_new_sale(): void {$p=$this->project();$plan=$this->plan($p);$d=$this->relay($p);$t=$this->paid($plan,$d);$wallet=app(DrinkWallet::class);$id=(string)\Illuminate\Support\Str::uuid();$this->invalid(fn()=>$wallet->redeem($t,250,'Before event',$id));$this->travelTo(\Carbon\Carbon::parse('2026-12-12 12:00'));$wallet->redeem($t,250,'Served',$id);$wallet->redeem($t,250,'Retry',$id);$this->assertSame(750,$t->drinkRemaining());$this->assertDatabaseCount('ticket_drink_redemptions',1);$this->assertDatabaseCount('event_tickets',1);$this->assertSame(100,$t->fresh()->relay_cents);$this->invalid(fn()=>$wallet->redeem($t,300,'Reused key',$id));$this->invalid(fn()=>$wallet->redeem($t,800,'Too much',(string)\Illuminate\Support\Str::uuid()));$this->invalid(fn()=>app(Ticketing::class)->refundCash($t,'Consumed',100));$this->travelTo(\Carbon\Carbon::parse('2026-12-12 23:00'));$this->invalid(fn()=>$wallet->redeem($t,100,'Bar closed',(string)\Illuminate\Support\Str::uuid()));auth('admin')->logout();$this->post(route('ticket.drinks',['ticket'=>$t->public_id]),['amount_cents'=>100,'evidence'=>'Intrusion','operation'=>(string)\Illuminate\Support\Str::uuid()])->assertForbidden();}
 public function test_shared_pelliste_is_only_interteam_exception_and_core_has_six_roles(): void {$p=$this->project();$a=$p->teams()->create(['name'=>'A','freguesia'=>'Souto']);$b=$p->teams()->create(['name'=>'B','freguesia'=>'Other']);$fill=['candidate_name'=>'Expert','candidate_reference'=>'person-1','status'=>'confirmed','consent_confirmed'=>true,'competence_evidence'=>'Proven trained driver','shared_operator'=>true,'sharing_evidence'=>'Both teams agree; distinct timed runs'];$one=$a->roleAssignments()->where('role_code','excavator_operator')->first();$two=$b->roleAssignments()->where('role_code','excavator_operator')->first();$one->update($fill);$two->update($fill);$this->assertTrue($one->fresh()->isCovered());$this->assertTrue($two->fresh()->isCovered());$this->assertSame(6,$a->fresh()->composition()['required']);$this->assertContains('musician',$a->fresh()->composition()['missing']);$this->invalid(fn()=>$b->roleAssignments()->where('role_code','cook')->first()->update(array_replace($fill,['shared_operator'=>false,'sharing_evidence'=>null])));$two->update(['sharing_evidence'=>'Modified schedule']);$this->assertSame('proposed',$two->fresh()->status);}
 public function test_meeting_priority_does_not_remove_other_relay_rights(): void {$p=$this->project();$d=$this->relay($p);$stand=$d->standPartner->stand;$large=$stand->partners()->create(['name'=>'Large café','relay_slot'=>2,'status'=>'active','mission'=>'Distribution','evidence'=>'Signed','meeting_candidate'=>true,'meeting_capacity'=>90,'meeting_capacity_evidence'=>'Measured usable room']);$small=$d->standPartner;$this->invalid(fn()=>$small->update(['hosts_information_meeting'=>true,'meeting_candidate'=>true,'meeting_capacity'=>30,'meeting_capacity_evidence'=>'Room measured']));$small->refresh();$small->update(['hosts_information_meeting'=>true,'meeting_candidate'=>true,'meeting_capacity'=>30,'meeting_capacity_evidence'=>'Measured','meeting_selection_reason'=>'Larger café unavailable on the agreed date','meeting_at'=>'2026-10-10 18:00','meeting_place'=>'Café','meeting_agreement'=>'Host confirmed']);$this->assertTrue($small->fresh()->hosts_information_meeting);$this->assertSame('active',$large->fresh()->status);$b=BarPartnership::create(['event_project_id'=>$p->id,'stand_partner_id'=>$small->id,'name'=>'Bar variant','commission_basis_points'=>1000,'forecast_ticket_sales_cents'=>100000,'forecast_other_costs_cents'=>5000]);$this->assertSame(10000,$b->forecastCommission());$this->invalid(fn()=>$b->update(['status'=>'active']));}
 public function test_junta_convention_and_community_prize_require_real_authority_and_result(): void {$p=$this->project();$stand=$this->relay($p)->standPartner->stand;$a=FreguesiaAgreement::create(['event_project_id'=>$p->id,'stand_id'=>$stand->id,'name'=>'Agreement','terms_version'=>'1','terms_fr'=>'Reviewed terms','terms_pt'=>'Termos revistos']);$this->invalid(fn()=>$a->update(['status'=>'signed']));$a->refresh();$a->update(['status'=>'signed','legal_entity'=>'Junta','signatory'=>'President','authority_evidence'=>'Deliberation','legal_review'=>'Professional review','agreement_evidence'=>'Signed document','signed_at'=>now()]);$this->assertTrue($a->signed());$this->invalid(fn()=>$a->update(['terms_fr'=>'Changed without version']));$s=$p->scenarios()->create(['name'=>'Budget']);$line=$s->budgetLines()->create(['name'=>'Community prize','kind'=>'cost','forecast_quantity'=>1,'unit_gross_cents'=>50000]);$team=$p->teams()->create(['name'=>'Winner','freguesia'=>$stand->freguesia]);$award=CommunityAward::create(['event_project_id'=>$p->id,'name'=>'Forquilha','budget_line_id'=>$line->id,'rules_fr'=>'Prize','rules_pt'=>'Prémio']);$this->invalid(fn()=>$award->update(['status'=>'awarded','winner_team_id'=>$team->id,'results_evidence'=>'Results','recipient_entity'=>'Junta','prize_project'=>'Christmas celebration']));$award->refresh();$this->travelTo(\Carbon\Carbon::parse('2026-12-14'));$award->update(['status'=>'awarded','winner_team_id'=>$team->id,'results_evidence'=>'Results','recipient_entity'=>'Junta','prize_project'=>'Christmas celebration']);$this->assertSame('awarded',$award->fresh()->status);$this->invalid(fn()=>$award->update(['status'=>'paid','paid_at'=>now(),'payment_evidence'=>'No bank payment yet']));}
 public function test_qr_is_unique_generic_private_until_activated_and_reports_are_idempotent(): void {$p=$this->project();$d=$this->relay($p);$f=$this->feature($p,'Secret equipment nearby');$point=ReportPoint::where('site_feature_id',$f->id)->firstOrFail();$this->assertSame('Point · '.$f->id,$point->name);ReportPoint::prepare($p);$this->assertDatabaseCount('report_points',2);$this->get($point->url())->assertNotFound();$point->update(['is_active'=>true,'placement_evidence'=>'QR placed; duty officer assigned']);$this->get($point->url())->assertOk()->assertDontSee('Secret equipment nearby')->assertDontSee('-7.4');$data=['submission_id'=>(string)\Illuminate\Support\Str::uuid(),'category'=>'water','report'=>'Leak near the tap','urgent'=>1,'privacy'=>1];$this->post($point->url(),$data)->assertRedirect();$this->post($point->url(),$data)->assertRedirect();$this->assertDatabaseCount('incidents',1);$i=Incident::first();$this->assertSame('stop',$i->severity);$this->get(\App\Filament\Pages\Dashboard::getUrl())->assertOk()->assertSee('water');$this->invalid(fn()=>$i->update(['status'=>'closed']));$i->refresh();$i->update(['status'=>'handled']);$this->assertNotNull($i->acknowledged_at);$i->update(['status'=>'closed','action'=>'Tap isolated and repaired']);$this->assertNotNull($i->closed_at);$this->invalid(fn()=>$i->update(['report'=>'Rewrite original']));auth('admin')->logout();$this->get(route('incident.sheet',['point'=>$point->public_id]))->assertForbidden();}
 public function test_small_sponsors_have_named_locations_and_private_print_proofs(): void {$p=$this->project();$f=$this->feature($p);$s=Sponsorship::create(['event_project_id'=>$p->id,'name'=>'Local support','scope'=>'signage','signage_feature_ids'=>[$f->id],'signage_deliverables'=>'Parking plaque 60x40, event dates, BAT before print','sponsor_name'=>'Local business','cash_pledged_cents'=>10000,'agreement_evidence'=>'Signed','agreed_at'=>now(),'web_rights'=>'Web attribution approved','status'=>'agreed']);$this->assertNull($s->slot_key);$this->get(route('sponsor.sheet',['sponsorship'=>$s->public_id]))->assertOk()->assertSee('Local business')->assertSee('NE PAS FABRIQUER');$this->invalid(fn()=>$s->update(['print_approved_at'=>now()]));$other=EventProject::create(['name'=>'Other','slug'=>'other-event']);$foreign=$this->feature($other);$this->invalid(fn()=>$s->update(['signage_feature_ids'=>[$foreign->id]]));}
 public function test_rally_is_reviewed_and_drawings_have_one_winner_per_freguesia(): void {$p=$this->project();$stand=$this->relay($p)->standPartner->stand;$stop=RallyStop::create(['event_project_id'=>$p->id,'stand_id'=>$stand->id,'name'=>'Tree and story']);$this->get(route('rally.show',['project'=>$p->slug]))->assertOk()->assertDontSee('Tree and story');$this->invalid(fn()=>$stop->update(['is_public'=>true]));$stop->refresh();$stop->update(['story_fr'=>'Une histoire','story_pt'=>'Uma história','nature_fr'=>'Un arbre','nature_pt'=>'Uma árvore','question_fr'=>'Que vois-tu ?','question_pt'=>'O que vês?','answer'=>'Private answer','review_evidence'=>'Village approved','safety_evidence'=>'Walk separate from machinery','is_public'=>true]);$this->get(route('rally.show',['project'=>$p->slug]))->assertSee('Tree and story')->assertDontSee('Private answer');$budget=$p->scenarios()->create(['name'=>'Budget'])->budgetLines()->create(['name'=>'Prize','kind'=>'cost','forecast_quantity'=>1,'unit_gross_cents'=>1000,'vat_basis_points'=>0,'pricing_status'=>'confirmed','price_source'=>'Quote','price_checked_at'=>now()]);$c=DrawingContest::create(['event_project_id'=>$p->id,'name'=>'Drawing','opens_at'=>'2026-12-12 10:00','closes_at'=>'2026-12-13 18:00','rules_fr'=>'Rules','rules_pt'=>'Regras','jury_evidence'=>'Independent jury','prize_description'=>'Art supplies','budget_line_id'=>$budget->id,'is_open'=>true]);$entry=['drawing_contest_id'=>$c->id,'stand_id'=>$stand->id,'name'=>'Child code 1','age_band'=>'6–9','guardian_contact'=>'parent@example.test','guardian_evidence'=>'Parent agrees to participation, no public photo','artwork_reference'=>'DRAW-1'];$this->invalid(fn()=>DrawingEntry::create($entry));$this->travelTo(\Carbon\Carbon::parse('2026-12-12 14:00'));$one=DrawingEntry::create($entry);$this->assertNotSame('parent@example.test',DB::table('drawing_entries')->where('id',$one->id)->value('guardian_contact'));$this->invalid(fn()=>DrawingEntry::create($entry));$two=DrawingEntry::create(array_replace($entry,['name'=>'Child code 2','artwork_reference'=>'DRAW-2']));$this->invalid(fn()=>$one->update(['status'=>'winner','jury_decision'=>'Too early']));$one->refresh();$this->travelTo(\Carbon\Carbon::parse('2026-12-13 19:00'));$one->update(['status'=>'winner','jury_decision'=>'Jury result']);$this->invalid(fn()=>$two->update(['status'=>'winner','jury_decision'=>'Second winner']));$this->get(route('rally.show',['project'=>$p->slug]))->assertDontSee('parent@example.test')->assertDontSee('Child code 1');}
 public function test_feedback_collects_every_audience_without_sending_and_replies_once_after_event(): void {$p=$this->project();$plan=$this->plan($p);$d=$this->relay($p);$this->paid($plan,$d,['email'=>'visitor@example.test']);$c=FeedbackCampaign::create(['event_project_id'=>$p->id,'name'=>'Thanks','body_fr'=>'Merci et votre avis','body_pt'=>'Obrigado e a sua opinião','send_after'=>'2026-12-14 10:00','closes_at'=>'2027-01-15','authorization'=>'Approved']);app(Feedback::class)->prepare($c);app(Feedback::class)->prepare($c);$this->assertDatabaseCount('feedback_invitations',2);$this->assertDatabaseHas('feedback_invitations',['audience'=>'relay']);$i=$c->invitations()->where('audience','visitor')->first();$this->get($i->url())->assertNotFound();$c->update(['is_enabled'=>true]);$this->get($i->url())->assertNotFound();Mail::fake();$i->update(['status'=>'ready']);$this->assertSame(0,app(Feedback::class)->tick());Mail::assertNothingSent();$this->travelTo(\Carbon\Carbon::parse('2026-12-14 12:00'));$this->get($i->url())->assertOk()->assertDontSee('visitor@example.test');$this->post($i->url(),['rating'=>5,'positive'=>'Village spirit','improvements'=>'More signs','privacy'=>1])->assertRedirect();$this->post($i->url(),['rating'=>1,'privacy'=>1])->assertRedirect();$this->assertSame(5,$i->fresh()->rating);$i->update(['status'=>'unknown']);$this->invalid(fn()=>$i->update(['status'=>'ready']));$this->assertSame(0,app(Feedback::class)->tick());}
 public function test_editorial_publication_requires_rights_and_returns_to_draft_after_edit(): void {$p=$this->project();$post=EditorialPost::create(['event_project_id'=>$p->id,'name'=>'Making-of','title_pt'=>'Bastidores','body_fr'=>'Secret before approval','body_pt'=>'Segredo']);$this->get(route('blog.show',['project'=>$p->slug,'post'=>$post->public_id]))->assertNotFound();$this->invalid(fn()=>$post->update(['status'=>'published','published_at'=>now()]));$post->refresh();$post->update(['rights_evidence'=>'All adults consent; music licensed','status'=>'published','published_at'=>now(),'youtube_id'=>'abcdEFgh123']);$this->get(route('blog.show',['project'=>$p->slug,'post'=>$post->public_id]))->assertOk()->assertSee('abcdEFgh123');$post->update(['body_pt'=>'Changed story']);$this->assertSame('draft',$post->fresh()->status);$this->get(route('blog.show',['project'=>$p->slug,'post'=>$post->public_id]))->assertNotFound();}
 public function test_all_community_forms_and_public_bilingual_pages_render(): void {$this->seed();$this->admin();foreach(['FreguesiaAgreement','CommunityAward','BarPartnership','ReportPoint','RallyStop','DrawingContest','DrawingEntry','FeedbackCampaign','FeedbackInvitation','EditorialPost'] as $name){$resource='App\\Filament\\Resources\\'.$name.'Resource';$this->get($resource::getUrl())->assertOk();\Livewire\Livewire::test($resource.'\\Pages\\ManageRecords')->mountAction('create')->assertHasNoActionErrors();}$p=EventProject::first();$p->update(['is_public'=>true]);foreach(['fr','pt'] as $locale)foreach(['community.show','rally.show','blog.index'] as $route)$this->get(route($route,['project'=>$p->slug,'lang'=>$locale]))->assertOk();}
}
